ticket-lock.pseudocode:
class TicketLock:
    def __init__(self):
        self.next = 0  # 다음 발급 번호
        self.owner = 0  # 현재 서비스 중인 번호

    def acquire(self):
        my = fetch_and_add(self, 'next', 1)  # 원자적 번호표
        while self.owner != my:
            pass  # 내 차례까지 스핀

    def release(self):
        self.owner += 1  # 다음 번호에게 넘김

time-quantum.pseudocode:
def round_robin(procs, q):  # procs: [(이름, 버스트)], 모두 0 도착
    ready = list(procs)
    t, done = 0, {}
    while ready:
        name, burst = ready.pop(0)
        run = min(q, burst)  # 최대 q만큼 실행
        t += run
        if burst > run:
            ready.append((name, burst - run))  # 큐 뒤로
        else:
            done[name] = t  # 완료 시각 = 반환시간
    return done

# round_robin([('A', 5), ('B', 3)], 2) → {'B': 7, 'A': 8}

timestamp-ordering.pseudocode:
def read(Ti, X):
    if TS[Ti] < W_TS[X]:  # 더 젊은 Tj가 이미 기록
        return restart(Ti)  # 새 타임스탬프로 재시작
    R_TS[X] = max(R_TS[X], TS[Ti])
    return X.value

def write(Ti, X, value, thomas=False):
    if TS[Ti] < R_TS[X]:  # 더 젊은 Tj가 이미 읽음
        return restart(Ti)
    if TS[Ti] < W_TS[X]:  # 더 젊은 Tj가 이미 기록
        if thomas:
            return  # 토마스 규칙: 무시
        return restart(Ti)
    X.value = value
    W_TS[X] = TS[Ti]
